void dfs(ll n){
    if(visited.find(n) != visited.end()) return;
    visited.insert(n);
    ll new_n;
    if(ump.find(n) != ump.end()){
        for(int l:ump[n]){
            new_n = n + l - 1;
            ans = max(ans, new_n);
            if(new_n !=n && ump.find(new_n) != ump.end()){
                dfs(new_n);
            }
        }
    }
}

